 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    flat = [v for row in grid for v in row]
    background = Counter(flat).most_common(1)[0][0]

    # The horizontal guide lines use a color other than the field/background.
    line_rows = []
    for r, row in enumerate(grid):
        mode, count = Counter(row).most_common(1)[0]
        if mode != background and count >= 0.6 * w:
            line_rows.append((r, mode))

    # At intersections the guide-line color is replaced by the data color.
    marked_cols = sorted({c for r, line_color in line_rows
                          for c, value in enumerate(grid[r])
                          if value != line_color})
    if len(line_rows) < 2 or len(marked_cols) < 2:
        return [[background]]

    out = []
    for (r0, _), (r1, _) in zip(line_rows, line_rows[1:]):
        row_out = []
        for c0, c1 in zip(marked_cols, marked_cols[1:]):
            corners = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
            row_out.append(corners[0] if all(v == corners[0] for v in corners) else background)
        out.append(row_out)
    return out
